import React, { useEffect, useRef, useState } from "react";
import CanvasJSReact from "@canvasjs/react-charts";

const { CanvasJSChart } = CanvasJSReact;

const BarChart = () => {
  const chartRef = useRef(null);
  const [chartData, setChartData] = useState(null);
  const [selectedBloodGroup, setSelectedBloodGroup] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch("http://localhost:5206/api/BloodRL/predict");
        if (response.ok) {
          const data = await response.json();
          setChartData(data);
          console.log(data);
        } else {
          console.error("Failed to fetch data:", response.status, response.statusText);
        }
      } catch (error) {
        console.error("An error occurred while fetching data:", error);
      }
    };

    fetchData();
  }, []);

  const handleBloodGroupChange = (event) => {
    setSelectedBloodGroup(event.target.value);
  };

  return (
    <div className="container">
      {chartData && (
        <div className="chart-container">
          <label htmlFor="bloodGroupSelect">Select Blood Group:</label>
          <select id="bloodGroupSelect" onChange={handleBloodGroupChange}>
            {Object.keys(chartData).map((bloodGroup) => (
              <option key={bloodGroup} value={bloodGroup}>
                {bloodGroup}
              </option>
            ))}
          </select>

          {selectedBloodGroup && (
            <div className="hospital-chart">
              <h3>{selectedBloodGroup} Blood Group</h3>
              <p className="prediction-message">Predicted Blood Availability for the Next Day</p>
              <CanvasJSChart
                options={{
                  animationEnabled: true,
                  theme: "dark2",
                  title: {
                    text: "Predicted Blood Availability for Tomorrow",
                  },
                  axisY: {
                    title: "Predicted Availability",
                    scaleBreaks: {
                      autoCalculate: true,
                      type: "wavy",
                      lineColor: "white",
                    },
                  },
                  data: [
                    {
                      type: "column",
                      indexLabel: "{y}",
                      indexLabelFontColor: "white",
                      dataPoints: Object.values(chartData[selectedBloodGroup]).map((item) => ({
                        label: item.hospitalName,
                        y: item.predictedAvailability,
                      })),
                    },
                  ],
                  data: [
                    {
                      type: "column",
                      indexLabel: "{y}",
                      indexLabelFontColor: "white",
                      dataPoints: Object.values(chartData[selectedBloodGroup]).map((item) => ({
                        label: item.actualAvailability,
                        y: item.predictedAvailability,
                      })),
                    },
                  ],
                }}
              />
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default BarChart;
